<script setup lang="ts">
import {computed} from 'vue'

// Toolbar icon set in src/assets/icons (generated by scripts/generate-icons.py)
const modules = import.meta.glob('../../../assets/icons/*.svg', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>
const icons: Record<string, string> = Object.fromEntries(
  Object.entries(modules).map(([path, url]) => [path.split('/').pop()!.replace('.svg', ''), url])
)

const props = withDefaults(defineProps<{name: string; size?: number}>(), {size: 22})

const src = computed(() => {
  const url = icons[props.name]
  if (!url) {
    console.warn(`[KbIcon] Unknown icon: ${props.name}`)
  }
  return url
})
</script>

<template>
  <img
    class="kb-icon"
    :src="src"
    :width="size"
    :height="size"
    alt=""
    aria-hidden="true"
    draggable="false"
  />
</template>

<style lang="scss">
.kb-icon {
  display: block;
  flex-shrink: 0;
  pointer-events: none;
  user-select: none;
}
</style>
